\section*{Claim}
For a single excitation in parity sector \(\sigma\in\{-1,+1\}\), with half-bandwidth set to \(2J=1\), transformed emitter amplitude \(\widetilde a_\sigma(\omega)\), detuning \(\Delta\), and coupling \(g\),
\[
\widetilde a_\sigma(\omega)=\left(\omega-\Delta-\sigma g^2+\sigma g^2\frac{\sqrt{\omega-\sigma}}{\sqrt{\omega+\sigma}}\right)^{-1}.
\]

\section*{Premises}
\begin{align*}
\text{(P1)}\quad & \sigma\in\{-1,+1\},\quad g>0,\quad \omega\in\mathbb C,\\
\text{(P2)}\quad & \widetilde a_\sigma(\omega) \text{ is defined by }D_\sigma(\omega)\widetilde a_\sigma(\omega)=1,\\
\text{(P3)}\quad & D_\sigma(\omega):=\omega-\Delta-\Sigma_\sigma(\omega),\\
\text{(P4)}\quad & \Sigma_\sigma(\omega):=\sigma g^2-\sigma g^2\frac{\sqrt{\omega-\sigma}}{\sqrt{\omega+\sigma}},\\
\text{(P5)}\quad & x^{-1}=1/x\text{ for every nonzero complex }x.
\end{align*}

\section*{Derivation}
\begin{align*}
D_\sigma(\omega)
&=\omega-\Delta-\Sigma_\sigma(\omega)
&&\text{by (P3)}\\
&=\omega-\Delta-\left(\sigma g^2-\sigma g^2\frac{\sqrt{\omega-\sigma}}{\sqrt{\omega+\sigma}}\right)
&&\text{substitution from (P4)}\\
&=\omega-\Delta-\sigma g^2+\sigma g^2\frac{\sqrt{\omega-\sigma}}{\sqrt{\omega+\sigma}}
&&\text{distribution of the minus sign.}
\end{align*}
\begin{align*}
D_\sigma(\omega)\widetilde a_\sigma(\omega)&=1
&&\text{by (P2)}\\
\widetilde a_\sigma(\omega)&=D_\sigma(\omega)^{-1}
&&\text{multiplication by }D_\sigma(\omega)^{-1}\\
&=\left(\omega-\Delta-\sigma g^2+\sigma g^2\frac{\sqrt{\omega-\sigma}}{\sqrt{\omega+\sigma}}\right)^{-1}
&&\text{using the derived denominator and (P5).}
\end{align*}

\section*{Final Result}
\[
\boxed{\widetilde a_\sigma(\omega)=\left(\omega-\Delta-\sigma g^2+\sigma g^2\frac{\sqrt{\omega-\sigma}}{\sqrt{\omega+\sigma}}\right)^{-1}}
\]
\hfill$\blacksquare$

