\section*{Claim}
In the transformed two-excitation Bloch representation, the amplitudes \(\widetilde A(\omega)\), \(\widetilde B_{p,q}(\omega)\) for \(p<q\), and \(\widetilde B_{q,q}(\omega)\) satisfy
\[
\widetilde A=\frac{1}{\omega-2\Delta}+\frac{gd}{\omega-2\Delta}\int_{-\pi/d}^{\pi/d}\left(e^{-iqd/2}\widetilde C_{2,q}+e^{iqd/2}\widetilde C_{1,q}\right)\frac{dq}{2\pi},
\]
\[
\widetilde B_{p,q}=\frac{g}{\omega-\omega_p-\omega_q}\sum_{j=1}^{2}\left(e^{ipd(3/2-j)}\widetilde C_{j,q}+e^{iqd(3/2-j)}\widetilde C_{j,p}\right),
\]
and
\[
\widetilde B_{q,q}=\frac{\sqrt 2 g}{\omega-2\omega_q}\sum_{j=1}^{2}e^{iqd(3/2-j)}\widetilde C_{j,q}.
\]

\section*{Premises}
\begin{align*}
\text{(P1)}\quad & x_1:=-d/2,\quad x_2:=d/2,\quad e^{iqx_1}=e^{-iqd/2},\quad e^{iqx_2}=e^{iqd/2},\\
\text{(P2)}\quad & e^{-iqx_j}=e^{iqd(3/2-j)}\quad\text{for }j\in\{1,2\},\\
\text{(P3)}\quad & (\omega-2\Delta)\widetilde A=1+g\sum_q\left(e^{iqx_1}\widetilde C_{2,q}+e^{iqx_2}\widetilde C_{1,q}\right),\\
\text{(P4)}\quad & (\omega-\omega_p-\omega_q)\widetilde B_{p,q}=g\sum_{j=1}^{2}\left(e^{-ipx_j}\widetilde C_{j,q}+e^{-iqx_j}\widetilde C_{j,p}\right),\quad p<q,\\
\text{(P5)}\quad & (\omega-2\omega_q)\widetilde B_{q,q}=\sqrt 2 g\sum_{j=1}^{2}e^{-iqx_j}\widetilde C_{j,q},\\
\text{(P6)}\quad & \sum_q F(q)=d\int_{-\pi/d}^{\pi/d}F(q)\frac{dq}{2\pi},\\
\text{(P7)}\quad & \omega\ne2\Delta,\quad \omega\ne\omega_p+\omega_q,\quad \omega\ne2\omega_q.
\end{align*}

\section*{Derivation}
\begin{align*}
(\omega-2\Delta)\widetilde A
&=1+g\sum_q\left(e^{iqx_1}\widetilde C_{2,q}+e^{iqx_2}\widetilde C_{1,q}\right)
&&\text{by (P3)}\\
&=1+gd\int_{-\pi/d}^{\pi/d}\left(e^{iqx_1}\widetilde C_{2,q}+e^{iqx_2}\widetilde C_{1,q}\right)\frac{dq}{2\pi}
&&\text{by (P6)}\\
&=1+gd\int_{-\pi/d}^{\pi/d}\left(e^{-iqd/2}\widetilde C_{2,q}+e^{iqd/2}\widetilde C_{1,q}\right)\frac{dq}{2\pi}
&&\text{by (P1)}.
\end{align*}
\begin{align*}
\widetilde A
&=\frac{1}{\omega-2\Delta}+\frac{gd}{\omega-2\Delta}\int_{-\pi/d}^{\pi/d}\left(e^{-iqd/2}\widetilde C_{2,q}+e^{iqd/2}\widetilde C_{1,q}\right)\frac{dq}{2\pi}
&&\text{division by }\omega-2\Delta\text{ using (P7).}
\end{align*}
\begin{align*}
(\omega-\omega_p-\omega_q)\widetilde B_{p,q}
&=g\sum_{j=1}^{2}\left(e^{-ipx_j}\widetilde C_{j,q}+e^{-iqx_j}\widetilde C_{j,p}\right)
&&\text{by (P4)}\\
&=g\sum_{j=1}^{2}\left(e^{ipd(3/2-j)}\widetilde C_{j,q}+e^{iqd(3/2-j)}\widetilde C_{j,p}\right)
&&\text{by (P2)},\\
\widetilde B_{p,q}
&=\frac{g}{\omega-\omega_p-\omega_q}\sum_{j=1}^{2}\left(e^{ipd(3/2-j)}\widetilde C_{j,q}+e^{iqd(3/2-j)}\widetilde C_{j,p}\right)
&&\text{division using (P7).}
\end{align*}
\begin{align*}
(\omega-2\omega_q)\widetilde B_{q,q}
&=\sqrt 2 g\sum_{j=1}^{2}e^{-iqx_j}\widetilde C_{j,q}
&&\text{by (P5)}\\
&=\sqrt 2 g\sum_{j=1}^{2}e^{iqd(3/2-j)}\widetilde C_{j,q}
&&\text{by (P2)},\\
\widetilde B_{q,q}
&=\frac{\sqrt 2 g}{\omega-2\omega_q}\sum_{j=1}^{2}e^{iqd(3/2-j)}\widetilde C_{j,q}
&&\text{division using (P7).}
\end{align*}

\section*{Final Result}
\[
\boxed{\begin{gathered}
\widetilde A=\frac{1}{\omega-2\Delta}+\frac{gd}{\omega-2\Delta}\int_{-\pi/d}^{\pi/d}\left(e^{-iqd/2}\widetilde C_{2,q}+e^{iqd/2}\widetilde C_{1,q}\right)\frac{dq}{2\pi},\\
