core_reasoning_6:
\section*{Claim}
For fixed \((\omega,z)\), the mobile poles in the contour integral of the secular equation are
\[
\zeta^{\pm1}(\omega,z)=-\delta\omega\pm\sqrt{\delta\omega+1}\sqrt{\delta\omega-1},
\qquad
\delta\omega:=\omega+\frac{z+z^{-1}}{2}.
\]
Moreover, \(\zeta(\omega,z)=\zeta(\omega,z^{-1})\), and if \(u=\zeta^{\pm1}(\omega,z)\), then \(z\) and \(z^{-1}\) are the two roots generated by replacing \(z\) with \(u\).

\section*{Premises}
\begin{align*}
\text{(P1)}\quad & \delta\omega(z):=\omega+\frac{z+z^{-1}}{2},\quad z\ne0,\\
\text{(P2)}\quad & z'\text{ is a mobile pole }\Longleftrightarrow 1+2\delta\omega(z)z'+z'^2=0,\\
\text{(P3)}\quad & x^2+2ax+1=0\Longrightarrow x=-a\pm\sqrt{a^2-1},\\
\text{(P4)}\quad & a^2-1=(a+1)(a-1),\\
\text{(P5)}\quad & \sqrt{(a+1)(a-1)}=\sqrt{a+1}\sqrt{a-1}\text{ on the chosen branches},\\
\text{(P6)}\quad & r_1,r_2\text{ roots of }x^2+2ax+1=0\Longrightarrow r_1+r_2=-2a,\quad r_1r_2=1.
\end{align*}

\section*{Derivation}
\begin{align*}
1+2\delta\omega(z)z'+z'^2&=0
&&\text{mobile-pole condition (P2)}\\
z'^2+2\delta\omega(z)z'+1&=0
&&\text{reordering}\\
z'&=-\delta\omega(z)\pm\sqrt{\delta\omega(z)^2-1}
&&\text{by (P3)}\\
&=-\delta\omega(z)\pm\sqrt{(\delta\omega(z)+1)(\delta\omega(z)-1)}
&&\text{by (P4)}\\
&=-\delta\omega(z)\pm\sqrt{\delta\omega(z)+1}\sqrt{\delta\omega(z)-1}
&&\text{by (P5).}
\end{align*}
\begin{align*}
\delta\omega(z^{-1})
&=\omega+\frac{z^{-1}+z}{2}
&&\text{by (P1)}\\
&=\omega+\frac{z+z^{-1}}{2}
&&\text{commutativity of addition}\\
&=\delta\omega(z)
&&\text{by (P1)},\\
\zeta(\omega,z^{-1})&=\zeta(\omega,z)
&&\text{because the formula for }\zeta\text{ depends on }z\text{ only through }\delta\omega(z).
\end{align*}
\begin{align*}
u&:=\zeta^{\pm1}(\omega,z)
&&\text{definition of one mobile pole}\\
u+u^{-1}&=-2\delta\omega(z)
&&\text{sum and product of roots by (P6)}\\
\delta\omega(u)&=\omega+\frac{u+u^{-1}}{2}
&&\text{by (P1)}\\
&=\omega-\delta\omega(z)
&&\text{substitution of }u+u^{-1}=-2\delta\omega(z)\\
&=\omega-\left(\omega+\frac{z+z^{-1}}{2}\right)
&&\text{by (P1)}\\
&=-\frac{z+z^{-1}}{2}.
\end{align*}
\begin{align*}
1+2\delta\omega(u)x+x^2
&=1-(z+z^{-1})x+x^2
&&\text{substitution of }\delta\omega(u)\\
&=x^2-(z+z^{-1})x+1
&&\text{reordering}\\
&=(x-z)(x-z^{-1})
&&\text{multiplication out.}
\end{align*}
\begin{align*}
1+2\delta\omega(u)x+x^2=0
&\Longleftrightarrow (x-z)(x-z^{-1})=0
&&\text{from the factorization above}\\
&\Longleftrightarrow x\in\{z,z^{-1}\}
&&\text{zero-product rule.}
\end{align*}

\section*{Final Result}
\[
\boxed{\zeta^{\pm1}(\omega,z)=-\delta\omega\pm\sqrt{\delta\omega+1}\sqrt{\delta\omega-1},\quad \zeta(\omega,z^{-1})=\zeta(\omega,z),\quad \zeta(\omega,\zeta(\omega,z))\in\{z,z^{-1}\}}
\]
\hfill$\blacksquare$

core_reasoning_8:
\section*{Claim}
Let
\[
S_0(\omega):=\sum_{\sigma,i}\alpha_\sigma(\omega,z_{\sigma i}),\qquad
S_1(\omega):=\sum_{\sigma,i}\sigma\alpha_\sigma(\omega,z_{\sigma i}).
\]
Then the transformed amplitude for both emitters being simultaneously excited is
\[
\widetilde A(\omega)=\frac{S_1(\omega)^2-S_0(\omega)^2}{2gS_0(\omega)}.
\]

\section*{Premises}
\begin{align*}
\text{(P1)}\quad & g>0,\\
\text{(P2)}\quad & S_0(\omega):=\sum_{\sigma,i}\alpha_\sigma(\omega,z_{\sigma i}),\\
\text{(P3)}\quad & S_1(\omega):=\sum_{\sigma,i}\sigma\alpha_\sigma(\omega,z_{\sigma i}),\\
\text{(P4)}\quad & \widetilde A(\omega)=\frac{1+2g\widetilde C_{1,2}(\omega)}{\omega-2\Delta},\\
\text{(P5)}\quad & 2g\widetilde C_{1,2}(\omega)=\frac{\omega-2\Delta}{2g}\frac{S_1(\omega)^2-S_0(\omega)^2}{S_0(\omega)}-1,\\
\text{(P6)}\quad & \omega\ne2\Delta,\quad S_0(\omega)\ne0\text{ before analytic continuation.}
\end{align*}

\section*{Derivation}
\begin{align*}
\widetilde A(\omega)
&=\frac{1+2g\widetilde C_{1,2}(\omega)}{\omega-2\Delta}
&&\text{by (P4)}\\
&=\frac{1+\left(\frac{\omega-2\Delta}{2g}\frac{S_1(\omega)^2-S_0(\omega)^2}{S_0(\omega)}-1\right)}{\omega-2\Delta}
&&\text{substitution from (P5)}\\
&=\frac{\frac{\omega-2\Delta}{2g}\frac{S_1(\omega)^2-S_0(\omega)^2}{S_0(\omega)}}{\omega-2\Delta}
&&\text{cancellation of }1-1\\
&=\frac{S_1(\omega)^2-S_0(\omega)^2}{2gS_0(\omega)}
&&\text{cancellation of }\omega-2\Delta\text{ using (P6).}
\end{align*}
\begin{align*}
S_0(\omega)&=\sum_{\sigma,i}\alpha_\sigma(\omega,z_{\sigma i})
&&\text{by (P2)},\\
S_1(\omega)&=\sum_{\sigma,i}\sigma\alpha_\sigma(\omega,z_{\sigma i})
&&\text{by (P3).}
\end{align*}

\section*{Final Result}
\[
\boxed{\widetilde A(\omega)=\frac{\left(\sum_{\sigma,i}\sigma\alpha_\sigma(\omega,z_{\sigma i})\right)^2-
\left(\sum_{\sigma,i}\alpha_\sigma(\omega,z_{\sigma i})\right)^2}{2g\sum_{\sigma,i}\alpha_\sigma(\omega,z_{\sigma i})}}
\]
\hfill$\blacksquare$

