\section*{Claim}
A two-excitation bound-state pole of \(\widetilde A(\omega)\) occurs at a real frequency \(\omega_b\) whenever
\[
\sum_{\sigma,i}\alpha_\sigma(\omega_b,z_{\sigma i})=0
\]
and the zero is simple and uncancelled by the numerator of \(\widetilde A(\omega)\).

\section*{Premises}
\begin{align*}
\text{(P1)}\quad & S_0(\omega):=\sum_{\sigma,i}\alpha_\sigma(\omega,z_{\sigma i}),\\
\text{(P2)}\quad & S_1(\omega):=\sum_{\sigma,i}\sigma\alpha_\sigma(\omega,z_{\sigma i}),\\
\text{(P3)}\quad & \widetilde A(\omega)=\frac{S_1(\omega)^2-S_0(\omega)^2}{2gS_0(\omega)},\quad g>0,\\
\text{(P4)}\quad & \omega_b\in\mathbb R,\quad S_0(\omega_b)=0,\quad S_0'(\omega_b)\ne0,\\
\text{(P5)}\quad & S_1(\omega_b)^2\ne0,\\
\text{(P6)}\quad & S_0(\omega)=S_0(\omega_b)+(\omega-\omega_b)S_0'(\omega_b)+O((\omega-\omega_b)^2),\\
\text{(P7)}\quad & S_1(\omega)^2-S_0(\omega)^2=S_1(\omega_b)^2+O(\omega-\omega_b)\text{ when (P4) and (P5) hold.}
\end{align*}

\section*{Derivation}
\begin{align*}
S_0(\omega)&=S_0(\omega_b)+(\omega-\omega_b)S_0'(\omega_b)+O((\omega-\omega_b)^2)
&&\text{by (P6)}\\
&=(\omega-\omega_b)S_0'(\omega_b)+O((\omega-\omega_b)^2)
&&\text{using }S_0(\omega_b)=0\text{ from (P4).}
\end{align*}
\begin{align*}
2gS_0(\omega)&=2g(\omega-\omega_b)S_0'(\omega_b)+O((\omega-\omega_b)^2)
&&\text{multiplication by }2g,\\
S_1(\omega)^2-S_0(\omega)^2&=S_1(\omega_b)^2+O(\omega-\omega_b)
&&\text{by (P7).}
\end{align*}
\begin{align*}
\widetilde A(\omega)
&=\frac{S_1(\omega)^2-S_0(\omega)^2}{2gS_0(\omega)}
&&\text{by (P3)}\\
&=\frac{S_1(\omega_b)^2+O(\omega-\omega_b)}{2g(\omega-\omega_b)S_0'(\omega_b)+O((\omega-\omega_b)^2)}
&&\text{substitute the local expansions}\\
&=\frac{S_1(\omega_b)^2}{2gS_0'(\omega_b)}\frac{1}{\omega-\omega_b}+O(1)
&&\text{because }S_1(\omega_b)^2\ne0\text{ and }S_0'(\omega_b)\ne0.
\end{align*}
\begin{align*}
\widetilde A(\omega)&\text{ has a simple pole at }\omega_b
&&\text{by the coefficient of }(\omega-\omega_b)^{-1}\text{ above.}
\end{align*}

\section*{Final Result}
\[
\boxed{\sum_{\sigma,i}\alpha_\sigma(\omega_b,z_{\sigma i})=0\quad\Longrightarrow\quad \widetilde A(\omega)\text{ has an uncancelled simple two-excitation bound-state pole at }\omega_b}
\]
\hfill$\blacksquare$

core_reasoning_10:
\section*{Claim}
If a one-excitation bound state has energy \(\epsilon_{\sigma i}\), then a bound-plus-free continuum in the two-excitation sector occupies
\[
[\epsilon_{\sigma i}-1,\epsilon_{\sigma i}+1],
\]
while the two-free-excitation continuum occupies \([-2,2]\). Therefore the endpoints \(\epsilon_{\sigma i}\pm1\) and \(\pm2\) are branch-point candidates for \(\widetilde A(\omega)\).

\section*{Premises}
\begin{align*}
\text{(P1)}\quad & \epsilon_{\sigma i}\in\mathbb R\text{ is a one-excitation bound-state energy},\\
\text{(P2)}\quad & \varepsilon\in[-1,1]\text{ is the dimensionless energy of one free waveguide excitation},\\
\text{(P3)}\quad & E_{\rm bf}:=\epsilon_{\sigma i}+\varepsilon,\\
\text{(P4)}\quad & \varepsilon_1,\varepsilon_2\in[-1,1]\text{ for two free waveguide excitations},\\
\text{(P5)}\quad & E_{\rm ff}:=\varepsilon_1+\varepsilon_2,\\
\text{(P6)}\quad & -1\le x\le1\Longrightarrow c-1\le c+x\le c+1,\\
\text{(P7)}\quad & -1\le x\le1\text{ and }-1\le y\le1\Longrightarrow -2\le x+y\le2,\\
\text{(P8)}\quad & \text{an endpoint of a continuum interval is a branch-point candidate for the transformed amplitude.}
\end{align*}

\section*{Derivation}
\begin{align*}
-1\le\varepsilon\le1
&\Longrightarrow \epsilon_{\sigma i}-1\le\epsilon_{\sigma i}+\varepsilon\le\epsilon_{\sigma i}+1
&&\text{by (P6) with }c:=\epsilon_{\sigma i}\\
&\Longrightarrow \epsilon_{\sigma i}-1\le E_{\rm bf}\le\epsilon_{\sigma i}+1
&&\text{substitution from (P3).}
\end{align*}
\begin{align*}
\{E_{\rm bf}:\varepsilon\in[-1,1]\}
&=\{\epsilon_{\sigma i}+\varepsilon:\varepsilon\in[-1,1]\}
&&\text{by (P3)}\\
&=[\epsilon_{\sigma i}-1,\epsilon_{\sigma i}+1]
&&\text{interval translation from the previous inequality.}
\end{align*}
\begin{align*}
\varepsilon_1,\varepsilon_2\in[-1,1]
&\Longrightarrow -2\le\varepsilon_1+\varepsilon_2\le2
&&\text{by (P7)}\\
&\Longrightarrow -2\le E_{\rm ff}\le2
&&\text{substitution from (P5).}
\end{align*}
\begin{align*}
\{E_{\rm ff}:\varepsilon_1,\varepsilon_2\in[-1,1]\}
&=[-2,2]
&&\text{Minkowski sum of }[-1,1]\text{ with itself.}
\end{align*}
\begin{align*}
E_{\rm bf}\in[\epsilon_{\sigma i}-1,\epsilon_{\sigma i}+1]
&\Longrightarrow \epsilon_{\sigma i}-1,\epsilon_{\sigma i}+1\text{ are continuum endpoints}
&&\text{by the first interval result}\\
E_{\rm ff}\in[-2,2]
&\Longrightarrow -2,2\text{ are continuum endpoints}
&&\text{by the second interval result}\\
&\Longrightarrow \epsilon_{\sigma i}\pm1\text{ and }\pm2\text{ are branch-point candidates}
&&\text{by (P8).}
\end{align*}

\section*{Final Result}
\[
\boxed{E_{\rm bf}\in[\epsilon_{\sigma i}-1,\epsilon_{\sigma i}+1],\qquad E_{\rm ff}\in[-2,2],\qquad \omega\in\{\epsilon_{\sigma i}\pm1,\pm2\}\text{ are continuum endpoints}}
\]
\hfill$\blacksquare$

