\section*{Claim}
In the Markovian two-excitation cascade, for \(|\Delta|<1\) and \(\Gamma>0\), the probability of finding exactly one emitter excited is
\[
P_1(t)=\frac{1-\Delta}{1+\Delta}e^{-(1-\Delta)\Gamma t}
+\frac{1+\Delta}{1-\Delta}e^{-(1+\Delta)\Gamma t}
-2\frac{1+\Delta^2}{1-\Delta^2}e^{-2\Gamma t}.
\]
At \(\Delta=0\), \(\max_{t\ge0}P_1(t)=1/2\), attained at \(\Gamma t=\log 2\).

\section*{Premises}
\begin{align*}
\text{(P1)}\quad & |\Delta|<1,\quad \Gamma>0,\quad t\ge0,\\
\text{(P2)}\quad & \lambda_+:=(1-\Delta)\Gamma,\quad \lambda_-:=(1+\Delta)\Gamma,\\
\text{(P3)}\quad & P_1(t):=\frac{\lambda_+}{\lambda_-}e^{-\lambda_+t}+\frac{\lambda_-}{\lambda_+}e^{-\lambda_-t}
-\frac{\lambda_+^2+\lambda_-^2}{\lambda_+\lambda_-}e^{-(\lambda_++\lambda_-)t},\\
\text{(P4)}\quad & \lambda_++\lambda_-=2\Gamma,\\
\text{(P5)}\quad & \lambda_+\lambda_-=(1-\Delta^2)\Gamma^2,\\
\text{(P6)}\quad & \lambda_+^2+\lambda_-^2=2(1+\Delta^2)\Gamma^2,\\
\text{(P7)}\quad & 0\le u\le1\Longrightarrow 2u-2u^2\le1/2,\text{ with equality iff }u=1/2.
\end{align*}

\section*{Derivation}
\begin{align*}
\frac{\lambda_+}{\lambda_-}
&=\frac{(1-\Delta)\Gamma}{(1+\Delta)\Gamma}
&&\text{by (P2)}\\
&=\frac{1-\Delta}{1+\Delta}
&&\text{cancel }\Gamma,\\
\frac{\lambda_-}{\lambda_+}
&=\frac{1+\Delta}{1-\Delta}
&&\text{same substitution and cancellation.}
\end{align*}
\begin{align*}
\frac{\lambda_+^2+\lambda_-^2}{\lambda_+\lambda_-}
&=\frac{2(1+\Delta^2)\Gamma^2}{(1-\Delta^2)\Gamma^2}
&&\text{by (P5) and (P6)}\\
&=2\frac{1+\Delta^2}{1-\Delta^2}
&&\text{cancel }\Gamma^2.
\end{align*}
\begin{align*}
P_1(t)
&=\frac{1-\Delta}{1+\Delta}e^{-(1-\Delta)\Gamma t}
