\section*{Claim}
If two excitations were independent and each excitation had probability \(p\in[0,1]\) of being held by the emitters, then the probability of finding exactly one emitter excitation would obey
\[
P_{\rm one}=2p(1-p)\le\frac{1}{2}.
\]
Therefore any observation of \(P_{\rm one}>1/2\) violates the independent-excitation bound used as a criterion for collective non-Markovian behavior.

\section*{Premises}
\begin{align*}
\text{(P1)}\quad & 0\le p\le1,\\
\text{(P2)}\quad & \text{independence gives }P_{\rm one}:=p(1-p)+(1-p)p,\\
\text{(P3)}\quad & (2p-1)^2\ge0,\\
\text{(P4)}\quad & A\le1/2\text{ and }B>1/2\Longrightarrow B>A.
\end{align*}

\section*{Derivation}
\begin{align*}
P_{\rm one}
&:=p(1-p)+(1-p)p
&&\text{by the independence rule (P2)}\\
&=2p(1-p)
&&\text{combine identical terms}\\
&=2p-2p^2
&&\text{expand.}
\end{align*}
\begin{align*}
(2p-1)^2&\ge0
&&\text{by (P3)}\\
4p^2-4p+1&\ge0
&&\text{expand the square}\\
-4p^2+4p&\le1
&&\text{multiply by }-1\text{ and reverse the inequality}\\
2p-2p^2&\le\frac{1}{2}
&&\text{divide by }2\\
P_{\rm one}&\le\frac{1}{2}
&&\text{substitute }P_{\rm one}=2p-2p^2.
\end{align*}
\begin{align*}
P_{\rm observed}>\frac{1}{2}
&\Longrightarrow P_{\rm observed}>P_{\rm one}\text{ for every independent value }p\in[0,1]
&&\text{by (P4)}\\
&\Longrightarrow P_{\rm observed}\text{ violates the independent-excitation bound.}
&&\text{definition of violation.}
\end{align*}

\section*{Final Result}
\[
\boxed{P_{\rm one}=2p(1-p)\le\frac{1}{2}\quad\text{for independent excitations; hence }P_{\rm observed}>\frac{1}{2}\text{ is a collective non-Markovian signature}}
\]
\hfill$\blacksquare$

