\section*{Claim}
For the critical case \(\Delta=0\) and \(g=1\) discussed in the paper, the two-free-continuum branch points at \(\omega=\pm2\) give a slower late-time algebraic contribution than a generic \(t^{-3/2}\) edge because
\[
A_{\pm2}(t)\sim \frac{e^{\mp2it}}{t\log^2 t}
\]
implies
\[
\frac{|A_{\pm2}(t)|}{t^{-3/2}}\sim\frac{t^{1/2}}{\log^2 t}\longrightarrow+\infty.
\]

\section*{Premises}
\begin{align*}
\text{(P1)}\quad & t>e,
\quad A_{\pm2}(t)\sim c_\pm\frac{e^{\mp2it}}{t\log^2 t},
\quad c_\pm\ne0,\\
\text{(P2)}\quad & |e^{\mp2it}|=1,\\
\text{(P3)}\quad & f(t)\sim g(t)\text{ and }g(t)>0\Longrightarrow |f(t)|\sim |g(t)|\text{ when the multiplicative constant is nonzero},\\
\text{(P4)}\quad & \lim_{t\to\infty}\frac{t^a}{(\log t)^b}=+\infty\quad\text{for }a>0\text{ and fixed }b>0,\\
\text{(P5)}\quad & \text{a contribution }f\text{ is asymptotically slower than }h\text{ if }|f(t)|/|h(t)|\to+\infty.
\end{align*}

\section*{Derivation}
\begin{align*}
A_{\pm2}(t)
&\sim c_\pm\frac{e^{\mp2it}}{t\log^2 t}
&&\text{by (P1)}\\
|A_{\pm2}(t)|
&\sim |c_\pm|\frac{|e^{\mp2it}|}{t\log^2 t}
&&\text{by (P3)}\\
&=|c_\pm|\frac{1}{t\log^2 t}
&&\text{by (P2).}
\end{align*}
\begin{align*}
\frac{|A_{\pm2}(t)|}{t^{-3/2}}
&\sim |c_\pm|\frac{1}{t\log^2 t}\cdot t^{3/2}
&&\text{substitute the asymptotic magnitude}\\
&=|c_\pm|\frac{t^{1/2}}{\log^2 t}
&&\text{combine powers of }t\\
&\longrightarrow+\infty
&&\text{by (P4) with }a=1/2\text{ and }b=2.
\end{align*}
\begin{align*}
\frac{|A_{\pm2}(t)|}{t^{-3/2}}\to+\infty
&\Longrightarrow A_{\pm2}(t)\text{ decays more slowly than a generic }t^{-3/2}\text{ edge}
&&\text{by (P5).}
\end{align*}

\section*{Final Result}
\[
\boxed{A_{\pm2}(t)\sim \frac{e^{\mp2it}}{t\log^2 t}\quad\Longrightarrow\quad \frac{|A_{\pm2}(t)|}{t^{-3/2}}\sim\frac{t^{1/2}}{\log^2 t}\to+\infty}
\]
\hfill$\blacksquare$
